entries[128805] = { ["name"] = "Potion of Fel Protection", ["text"] = "Binds when picked up\nUnique\nUse: A potent concoction that reduces all damage taken by 10% for 10 min. Does not work on players over level 49. (3 Sec Cooldown)" }
entries[128807] = { ["name"] = "Coin of Many Faces", ["text"] = "Toy\nUse: Become someone else.\nCooldown reduced during Hallow's End. (1 Day Cooldown)\nSell Price:" }
entries[128808] = { ["name"] = "Talonclaw", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Polearm\n3 - 7 Damage Speed 3.60\n(1.4 damage per second)\n+2 Agility\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nStorm Artifact Relic Slot\nIron Artifact Relic Slot\n\nClasses: Hunter\nEquip: Grants the Fury of the Eagle ability, which unleashes an unrelenting series of frontal spear strikes.\n\"The Eagle Spear. Spear of the Wild Gods. Talonclaw. Bearing many names and many blessings, this is a weapon of legends.\"\nSell Price:" }
entries[128809] = { ["name"] = "New Recruit", ["text"] = "Quest Item\nUnique\n\"Highlord Mograine will bring back one of our knights, but who?\"" }
entries[128810] = { ["name"] = "Jar of Spiders", ["text"] = "Binds when picked up\nUnique\n\"A fascinating specimen!\"" }
entries[128813] = { ["name"] = "Fel Energy Core", ["text"] = "Quest Item\n\"A pulsating core filled with fel energy.\"" }
entries[128814] = { ["name"] = "Potion of Cowardly Flight", ["text"] = "Sell Price:" }
entries[128819] = { ["name"] = "Doomhammer", ["text"] = "Binds when picked up\nUnique\nMain Hand Mace\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nFire Artifact Relic Slot\nIron Artifact Relic Slot\n\nClasses: Shaman\nEquip: Grants the Doom Winds ability, causing you to unleash Windfury on your opponents.\n\"A stranger will raise the hammer high, and with it justice shall reign.\"\nSell Price:" }
entries[128820] = { ["name"] = "Felo'melorn", ["text"] = "Binds when picked up\nUnique\nMain Hand Sword\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n+6 Intellect\n+2 Stamina\n+ 1 Haste\n+ 1 Mastery\n\nFire Artifact Relic Slot\nArcane Artifact Relic Slot\n\nClasses: Mage\nEquip: Grants the Phoenix's Flames ability, which hurls destructive fire at all enemies near your target.\n\"...not elven weapons. Not when they are reforged with magic, and hatred, and a burning need for revenge. No, Arthas. Felo'melorn is stronger than ever-as am I. - Kael'thas Sunstrider\"\nSell Price:" }
entries[128821] = { ["name"] = "Claws of Ursoc", ["text"] = "Binds when picked up\nUnique\nMain Hand Fist Weapon\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nFire Artifact Relic Slot\nBlood Artifact Relic Slot\n\nClasses: Druid\nEquip: Grants the Rage of the Sleeper ability, which greatly empowers you with the avatar of Ursoc.\n\"Ursoc, brother of Ursol and guardian of the furbolg tribes... bearer of the strength of the forest itself.\"\nSell Price:" }
entries[128822] = { ["name"] = "Claws of Ursoc", ["text"] = "Binds when picked up\nUnique\nOff Hand Fist Weapon\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Druid\n\"Azeroth will need you. If you do not stand ready, the world may fall.\"\nSell Price:" }
entries[128823] = { ["name"] = "The Silver Hand", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Mace\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nHoly Artifact Relic Slot\nLife Artifact Relic Slot\n\nClasses: Paladin\nEquip: Armor increased by 30%.\nEquip: Grants the Tyr's Deliverance ability, which unleashes a torrent of healing on nearby allies. (Proc chance: 6%)\n\"Tyr replied that he did not consider his argent hand a reminder of defeat. For him it was a symbol of the sacrifice he had made to defend Azeroth, and he wanted the world to see it that way as well.\"\nSell Price:" }
entries[128824] = { ["name"] = "Tome of the Silver Hand", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n47 Armor\n+7 Intellect\n+4 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\nClasses: Paladin\n\"Esarus thar no'Darador.\"\nSell Price:" }
entries[128825] = { ["name"] = "T'uure, Beacon of the Naaru", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nHoly Artifact Relic Slot\nLife Artifact Relic Slot\n\nClasses: Priest\nEquip: Your Holy Word spells have a chance to summon an image of T'uure at your side to aid you in combat.\n\"Blessed are the torchbearers, who bring light to the darkness.\"\nSell Price:" }
entries[128826] = { ["name"] = "Thas'dorah, Legacy of the Windrunners", ["text"] = "Binds when picked up\nUnique\nRanged Bow\n3 - 5 Damage Speed 3.00\n(1.3 damage per second)\n+2 Agility\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nStorm Artifact Relic Slot\nBlood Artifact Relic Slot\n\nClasses: Hunter\nEquip: Grants access to the Windburst ability, which deals massive damage to a target and increases allies' movement speed in the arrow's path.\n\"When it was retrieved from the Sunwell, the bow radiated power. Talanas was humbled by the gift. He named the weapon Thas'dorah, \"Valor of the Forest.\"\"\nSell Price:" }
entries[128827] = { ["name"] = "Xal'atath, Blade of the Black Empire", ["text"] = "Binds when picked up\nUnique\nMain Hand Dagger\n1 Damage Speed 1.80\n(0.6 damage per second)\n+6 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nShadow Artifact Relic Slot\nBlood Artifact Relic Slot\n\nClasses: Priest\nEquip: Grants the Void Torrent ability, which unleashes massive shadowy damage, and delays your descent from madness.\n\"Xal'atath has a mind of its own. Ignore its maddening whispers. Do not trust the lies it spins. Take from it what you need, but always remember that the dark presence in the blade is not your ally.\"\nSell Price:" }
entries[128831] = { ["name"] = "Aldrachi Warblades", ["text"] = "Binds when picked up\nUnique\nOff Hand Warglaive\n2 - 4 Damage Speed 2.60\n(1.2 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Demon Hunter\n\"His warblades howled over the clamor of battle, rending anything that came near. Each demon Toranaar vanquished seemed to fill him with renewed vigor and strength. He was an army unto himself.\"" }
entries[128832] = { ["name"] = "Aldrachi Warblades", ["text"] = "Binds when picked up\nUnique\nMain Hand Warglaive\n2 - 4 Damage Speed 2.60\n(1.2 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nIron Artifact Relic Slot\nArcane Artifact Relic Slot\n\nClasses: Demon Hunter\nEquip: Grants the Soul Carver ability, which slashes your target for Fire damage and tears Lesser Soul Fragments from them.\n\"The Aldrachi were a proud race. Too proud to serve. Millions of demons died before the Aldrachi were wiped out, and it took Sargeras himself to kill their king.\"" }
