entries[128858] = { ["name"] = "Scythe of Elune", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nArcane Artifact Relic Slot\nLife Artifact Relic Slot\n\nClasses: Druid\nEquip: Grants the New Moon spell, which deals damage and then transforms into a more powerful spell.\n\"There is power within that would be freed. With balance and control, the wolf may be tamed, but only for a time.\"\nSell Price:" }
entries[128859] = { ["name"] = "Fangs of Ashamane", ["text"] = "Binds when picked up\nUnique\nOff Hand Dagger\n1 - 3 Damage Speed 1.80\n(1.1 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Druid\n\"She ripped through the demons' ranks and then disappeared into the trees. She crept along the high branches and dove down upon the Legion commanders. She was a terror, a fearsome beast, and she held nothing back, offering no mercy.\"\nSell Price:" }
entries[128860] = { ["name"] = "Fangs of Ashamane", ["text"] = "Binds when picked up\nUnique\nMain Hand Dagger\n1 - 3 Damage Speed 1.80\n(1.1 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nFrost Artifact Relic Slot\nBlood Artifact Relic Slot\n\nClasses: Druid\nEquip: Grants the Ashamane's Frenzy ability, which unleashes a flurry of bloody slashes on an enemy target.\n\"The sacrifice of Ashamane is remembered to this day. We live by her grace, and her children still tread the forests with us as our closest companions.\"\nSell Price:" }
entries[128861] = { ["name"] = "Titanstrike", ["text"] = "Binds when picked up\nUnique\nRanged Gun\n3 - 6 Damage Speed 3.00\n(1.5 damage per second)\n+2 Agility\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nStorm Artifact Relic Slot\nArcane Artifact Relic Slot\n\nClasses: Hunter\nEquip: Hati will now fight for you as a companion.\n\"A peerless example of techno-magical engineering, infused with the power of storms.\"\nSell Price:" }
entries[128862] = { ["name"] = "Ebonchill", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\n\nFrost Artifact Relic Slot\nArcane Artifact Relic Slot\n\nClasses: Mage\nEquip: Grants the Ebonbolt ability, which deals massive Shadowfrost damage to a single target.\n\"Ebonchill contained only a sliver of Alodi's might, but even that was more than most magi could ever hope of wielding.\"\nSell Price:" }
entries[128864] = { ["name"] = "The Rocky Hills of Highmountain", ["text"] = "Quest Item\n\"Goat saliva has caused the ink to run and blur.\"" }
entries[128866] = { ["name"] = "Truthguard", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n25 Armor\n+1 Strength\n+3 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nHoly Artifact Relic Slot\nIron Artifact Relic Slot\n\nClasses: Paladin\nEquip: Grants the Eye of Tyr ability, which unleashes a burst of light from your shield, weakening nearby enemies.\n\"With the first hammer fall, rivers of magma spilled from the icy mountains. With the second, the sky howled and lightning set the heavens aflame. With the third, a single ray of sunlight pierced the storm clouds and whispered over Truthguard's surface.\"\nSell Price:" }
entries[128867] = { ["name"] = "Oathseeker", ["text"] = "Binds when picked up\nUnique\nMain Hand Sword\n2 - 4 Damage Speed 2.60\n(1.2 damage per second)\n+1 Strength\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Paladin\n\"Killing for the sake of killing... conquering for the sake of conquest... there is no honor in such things. There is only shame and regret.\"\nSell Price:" }
entries[128868] = { ["name"] = "Light's Wrath", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\n\nHoly Artifact Relic Slot\nShadow Artifact Relic Slot\n\nClasses: Priest\nEquip: Grants the Light's Wrath ability, which unleashes a torrent of Holy Fire upon an enemy. (Proc chance: 15%)\n\"It was with our greatest hopes and prayers that we attended the ceremony that day... and it is with our greatest sorrows that we departed it.\"\nSell Price:" }
entries[128869] = { ["name"] = "The Kingslayers", ["text"] = "Sorrow\nBinds when picked up\nUnique\nOff Hand Dagger\n1 - 3 Damage Speed 1.80\n(1.1 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Rogue\n\"It was not a pleasant death. But it was fast, quiet, and efficient. When the orc took his last breath, the wound that killed him became irregular. Nobody would be able to tell whether he had died to a knife, an axe, or a spear.\"\nSell Price:" }
entries[128870] = { ["name"] = "The Kingslayers", ["text"] = "Anguish\nBinds when picked up\nUnique\nMain Hand Dagger\n1 - 3 Damage Speed 1.80\n(1.1 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nShadow Artifact Relic Slot\nIron Artifact Relic Slot\n\nClasses: Rogue\nEquip: Grants you the Kingsbane ability, which injects your target with a poison of unrivaled potency.\n\"Countless voices hushed, and countless leaders toppled... all at the whim of his foul command. There would be no redemption for these acts, only solitude and sorrow.\"\nSell Price:" }
entries[128872] = { ["name"] = "The Dreadblades", ["text"] = "Fate\nBinds when picked up\nUnique\nMain Hand Sword\n2 - 4 Damage Speed 2.60\n(1.2 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nBlood Artifact Relic Slot\nIron Artifact Relic Slot\n\nClasses: Rogue\nEquip: Grants the Curse of the Dreadblades ability, which lets you use finishers more rapidly... at a price.\n\"She saw herself commanding an impossibly large pirate fleet, one that could conquer the high seas and all the nations of Azeroth. Every ship that dared to challenge her burned, and every city gave up its treasures or was destroyed.\"\nSell Price:" }
entries[128873] = { ["name"] = "Fury of the Stonemother", ["text"] = "Binds when picked up\nUnique\nOff Hand Mace\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Shaman\n\"Created through the power of Doomhammer and the powerful shaman who wields it.\"\nSell Price:" }
