entries[128908] = { ["name"] = "Warswords of the Valarjar", ["text"] = "Odyn's Fury\nBinds when picked up\nUnique\nTwo-Hand Sword\n3 - 7 Damage Speed 3.60\n(1.4 damage per second)\n+2 Strength\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nFire Artifact Relic Slot\nStorm Artifact Relic Slot\n\nClasses: Warrior\nEquip: Grants the Odyn's Fury ability, which unleashes massive Fire damage on nearby enemies.\n\"Helya's betrayal shall never be forgiven. Let her rot beneath the waves, far from the Halls of Valor.\"\nSell Price:" }
entries[128910] = { ["name"] = "Strom'kar, the Warbreaker", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Sword\n3 - 7 Damage Speed 3.60\n(1.4 damage per second)\n+2 Strength\n+3 Stamina\n+ 2 Critical Strike\n+ 2 Mastery\n\nIron Artifact Relic Slot\nBlood Artifact Relic Slot\n\nClasses: Warrior\nEquip: Grants the Warbreaker ability, which deals massive damage in an area and makes opponents vulnerable.\n\"The steel of the barbarian king shall strike the final blow. It shall silence the din of battle, and bring the first kingdom into an age of peace.\"\nSell Price:" }
entries[128911] = { ["name"] = "Sharas'dal, Scepter of Tides", ["text"] = "Binds when picked up\nUnique\nMain Hand Mace\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n+6 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nLife Artifact Relic Slot\nFrost Artifact Relic Slot\n\nClasses: Shaman\nEquip: Grants the Gift of the Queen ability, healing allies for massive amounts and increasing their maximum health.\n\"They drifted into the abyss, but Azshara and her Highborne remained unbroken. The darkness around them was absolute, and so the queen willed Sharas'dal to bring them light...\"\nSell Price:" }
entries[128912] = { ["name"] = "Blight Sample", ["text"] = "Binds when picked up\nUnique" }
entries[128921] = { ["name"] = "Spellsludge", ["text"] = "Quest Item\n\"The accumulated sludge of a city of mages.\"" }
entries[128922] = { ["name"] = "Alchemical Flame", ["text"] = "Quest Item\n\"Known more colloquially among alchemists as \"Liquid Hot\".\"" }
entries[128923] = { ["name"] = "Spellbound Insulation", ["text"] = "Quest Item\n\"Specially formulated to insulate against both heat and ley energy.\"" }
entries[128924] = { ["name"] = "Decommissioned Calefactor", ["text"] = "Quest Item\n\"More mechanical than magical. Perhaps this came from the engineering shop?\"" }
entries[128933] = { ["name"] = "Rashar's Right Eye", ["text"] = "Quest Item\n\"The amber eye has a soft, warm glow that invites a closer look.\"" }
entries[128934] = { ["name"] = "Shield of the Sea Queen", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n25 Armor\n+1 Strength\n+3 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Shaman\n\"As the ocean crushed the life from their bodies, ancient creatures stirred in the darkness. Their whispers flowed through the currents. Their powers wrapped tight around the queen and her servants.\"\nSell Price:" }
entries[128935] = { ["name"] = "The Fist of Ra-den", ["text"] = "Binds when picked up\nUnique\nMain Hand Fist Weapon\n1 - 2 Damage Speed 2.60\n(0.6 damage per second)\n+6 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nStorm Artifact Relic Slot\nFrost Artifact Relic Slot\n\nClasses: Shaman\nEquip: Grants the Stormkeeper ability, which massively empowers your Lightning Bolts or Chain Lightnings.\n\"To seal Al'Akir's demise, Master Ra slammed his fist into the mountaintop. The heavens split wide, and all the fire and fury they contained crashed down atop the Windlord's head.\"\nSell Price:" }
entries[128936] = { ["name"] = "The Highkeeper's Ward", ["text"] = "Binds when picked up\nUnique\nOff Hand Shield\n25 Armor\n+1 Strength\n+3 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\nClasses: Shaman\n\"Ra and Helya crafted a shield, the Highkeeper's Ward, to act as a key to the Elemental Plane. It thrummed with the energies of the four elements, which Ra could call upon whenever he desired.\"\nSell Price:" }
entries[128937] = { ["name"] = "Sheilun, Staff of the Mists", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\n\nFrost Artifact Relic Slot\nLife Artifact Relic Slot\n\nClasses: Monk\nEquip: Grants you the Sheilun's Gift spell, which significantly heals an ally.\n\"You seek the calm, inevitable force of a deep river, the kind that carves canyons into the toughest stone and carries away warriors on its currents without so much as a ripple. Sheilun is the embodiment of that idea.\"\nSell Price:" }
entries[128938] = { ["name"] = "Fu Zan, the Wanderer's Companion", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n4 - 6 Damage Speed 3.60\n(1.4 damage per second)\n+2 Agility\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\n\nLife Artifact Relic Slot\nStorm Artifact Relic Slot\n\nClasses: Monk\nEquip: Grants the Exploding Keg ability, which does exactly what you think it will do.\n\"From the beginning, this staff has accompanied legendary creatures and immortal spirits as they carried out important, lasting work all across Azeroth.\"\nSell Price:" }
entries[128940] = { ["name"] = "Fists of the Heavens", ["text"] = "Al'burq\nBinds when picked up\nUnique\nMain Hand Fist Weapon\n2 - 3 Damage Speed 2.60\n(1.0 damage per second)\n+1 Agility\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nStorm Artifact Relic Slot\nIron Artifact Relic Slot\n\nClasses: Monk\nEquip: Grants the Strike of the Windlord ability, a fierce double attack that also cripples your foe.\n\"When Irmaat hefted his two weapons and tested the power within them, uncontrollable fury spilled forth.\"\nSell Price:" }
entries[128941] = { ["name"] = "Scepter of Sargeras", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\n\nFel Artifact Relic Slot\nFire Artifact Relic Slot\n\nClasses: Warlock\nEquip: Grants the Dimensional Rift ability, which rips open portals in time and space, unleashing devastating damage on your enemies.\n\"When at last the moment arrived for Ner'zhul to act, he did so with wild abandon, heedless of the consequences. It mattered not to him if Draenor was destroyed; in fact, he welcomed it as part of his legacy.\"\nSell Price:" }
entries[128942] = { ["name"] = "Ulthalesh, the Deadwind Harvester", ["text"] = "Binds when picked up\nUnique\nTwo-Hand Staff\n2 - 3 Damage Speed 3.60\n(0.7 damage per second)\n+9 Intellect\n+3 Stamina\n+ 2 Haste\n+ 2 Mastery\n\nShadow Artifact Relic Slot\nBlood Artifact Relic Slot\n\nClasses: Warlock\nEquip: Grants the Reap Soul ability, consuming the souls of fallen foes to empower Ulthalesh .\n\"The scythe's master will either overcome Sataiel or be consumed, which will only make the blade more powerful. And then another bearer will take their place. And another.\"\nSell Price:" }
entries[128943] = { ["name"] = "Skull of the Man'ari", ["text"] = "Binds when picked up\nUnique\nHeld In Off-hand\n+3 Intellect\n+2 Stamina\n+ 1 Critical Strike\n+ 1 Mastery\n\nShadow Artifact Relic Slot\nFire Artifact Relic Slot\n\nClasses: Warlock\nEquip: Grants the Thal'kiel's Consumption ability, which dispatches Thal'kiel to torment an enemy.\n\"When finally Thal'kiel emerged, he was changed. He had aged by centuries, alone in the dark with his thoughts and his thralls. His back was twisted and stooped, and there was an odd glimmer in his eye. He summoned his Wakeners, and we answered the call...\"\nSell Price:" }
